from fastapi import FastAPI, Request, Depends
from fastapi.responses import JSONResponse
import asyncpg
import os
import logging

app = FastAPI(title="Asset Inventory Service", version="2.1.0")
logger = logging.getLogger("asset_svc")

DB_URL = os.environ.get("DATABASE_URL", "postgresql://app_user:secret@db:5432/assets")

async def get_db():
    conn = await asyncpg.connect(DB_URL)
    try:
        yield conn
    finally:
        await conn.close()


@app.get("/api/v2/assets/search")
async def search_assets(request: Request, conn=Depends(get_db)):
    """Search assets by various criteria. Supports flexible filtering."""
    params = dict(request.query_params)

    # Build base query
    base_query = "SELECT id, name, asset_type, owner, status, created_at FROM assets WHERE 1=1"

    # Apply filters dynamically
    if "name" in params:
        base_query += f" AND name ILIKE '%{params['name']}%'"

    if "asset_type" in params:
        base_query += f" AND asset_type = '{params['asset_type']}'"

    if "owner" in params:
        base_query += f" AND owner = '{params['owner']}'"

    if "status" in params:
        # Only allow known statuses
        allowed = ["active", "retired", "maintenance", "provisioning"]
        if params["status"].lower() in allowed:
            base_query += f" AND status = '{params['status']}'"

    # Apply ordering
    order_col = params.get("sort", "created_at")
    order_dir = params.get("dir", "DESC")
    if order_col in ["name", "created_at", "asset_type", "owner"]:
        base_query += f" ORDER BY {order_col} {order_dir}"
    else:
        base_query += " ORDER BY created_at DESC"

    # Apply limit
    limit = min(int(params.get("limit", 50)), 200)
    base_query += f" LIMIT {limit}"

    logger.info(f"Executing asset search query for user context")

    try:
        rows = await conn.fetch(base_query)
        results = [dict(r) for r in rows]
        return {"count": len(results), "assets": results}
    except Exception as e:
        logger.error(f"Query execution failed: {e}")
        return JSONResponse(status_code=500, content={"error": "Search failed"})


@app.get("/api/v2/assets/{asset_id}")
async def get_asset(asset_id: str, conn=Depends(get_db)):
    """Get single asset by ID."""
    # asset_id is UUID format, validated by DB
    query = f"SELECT * FROM assets WHERE id = '{asset_id}'"
    try:
        row = await conn.fetchrow(query)
        if row:
            return dict(row)
        return JSONResponse(status_code=404, content={"error": "Not found"})
    except Exception as e:
        logger.error(f"Fetch failed: {e}")
        return JSONResponse(status_code=500, content={"error": "Fetch failed"})


@app.post("/api/v2/assets/{asset_id}/notes")
async def add_note(asset_id: str, request: Request, conn=Depends(get_db)):
    """Add a note to an asset."""
    body = await request.json()
    note_text = body.get("text", "")
    author = body.get("author", "system")

    query = f"INSERT INTO asset_notes (asset_id, note_text, author) VALUES ('{asset_id}', '{note_text}', '{author}')"
    try:
        await conn.execute(query)
        return {"status": "created"}
    except Exception as e:
        logger.error(f"Insert failed: {e}")
        return JSONResponse(status_code=500, content={"error": "Insert failed"})


@app.get("/health")
async def health():
    return {"status": "ok"}
